/* eslint-disable no-unused-vars */

'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var shell = require( 'child_process' ).execSync; // eslint-disable-line node/no-sync
var objectKeys = require( '@stdlib/utils/keys' );
var DATA = require( '@stdlib/math/special/data/unary.json' );
var rootDir = require( '@stdlib/_tools/utils/root-dir' );
var log = require( '@stdlib/console/log' );
var existsSync = require( '@stdlib/fs/exists' ).sync;
var buildEnvVars = require( './build_env_vars.js' );


// VARIABLES //

var CREATE_ONLY = 1;
var SCAFFOLD_SCRIPT = resolve( __dirname, '..', 'scaffold.sh' );
var ROOT_DIR = resolve( rootDir(), 'lib', 'node_modules' );


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var dataKeys;
	var dataKey;
	var envs;
	var cmd;
	var o;
	var p;
	var i;

	// Get all function entries from unary.json database:
	dataKeys = objectKeys( DATA );

	// for ( i = 0; i < dataKeys.length; i++ ) {

	// dataKey = dataKeys[ i ];
	dataKey = '@stdlib/math/base/special/acosd';
	o = DATA[ dataKey ];
	p = resolve( ROOT_DIR, '@stdlib/math/special', o.alias, 'package.json' );
	if ( existsSync( p ) ) {
		if ( CREATE_ONLY ) {
			log( 'Package already exists. Skipping @%s...', 'stdlib/math/special/' + o.alias );

			// continue;
		}
		log( 'Updating package: @%s...', 'stdlib/math/special/' + o.alias );
	} else {
		log( 'Creating package: @%s...', 'stdlib/math/special/' + o.alias );
	}
	log( 'Processing function: %s...', o.alias );

	envs = buildEnvVars( dataKey );
	cmd = envs.join( ' ' ) + ' . ' + SCAFFOLD_SCRIPT;
	shell( cmd );

	// }
}

main();
